"use strict";
(()=>{const L=window.Lab;if(!L||!L.$('rlc-lab'))return;
L.init(['resistance','voltage','current'],()=>{const R=L.range('resistance'),vc0=L.range('voltage'),i0=L.range('current'),f=t=>{const s=L.homogeneous(R,vc0-1,i0/.25,t);return{v:1+s.x,i:.25*s.v}};const g=L.$('drawing');g.replaceChildren();const a=L.svg('g'),b=L.svg('g',{transform:'translate(0,275)'});g.append(a,b);L.plot(a,[{fn:t=>f(t).v}],{yMin:-.5,yMax:2.5,yLabel:'電容電壓 vC（V）',height:270});L.plot(b,[{fn:t=>f(t).i,color:'#cf604b'}],{yMin:-1,yMax:1,yLabel:'串聯電流 i（A）',height:270});const s=f(1),ec=.125*s.v*s.v,el=.5*s.i*s.i;L.text('result-primary',L.fmt(s.v)+' V');L.text('result-secondary',L.fmt(s.i)+' A');L.text('feedback','1 s 時：電容儲能 '+L.fmt(ec)+' J，電感儲能 '+L.fmt(el)+' J；電阻耗散功率 R i² = '+L.fmt(R*s.i*s.i)+' W。初始斜率 vC′(0+) = i₀/C = '+L.fmt(i0/.25)+' V/s。'+(vc0===1&&i0===0?'起始已在平衡狀態：電容始終 1 V、電流始終 0 A，沒有振盪。':R===0?'R=0 不耗能，理想模型會持續振盪；不能說它最後停在 1 V。':'R>0 時暫態衰減，最後 vC=1 V、i=0 A。')+' 上下圖使用不同物理單位，不能直接比較線的高低。');});})();
